import{_ as s,o as t,c as e,ai as n}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"Redis","description":"","frontmatter":{},"headers":[],"relativePath":"redis/index.md","filePath":"redis/index.md"}'),r={name:"redis/index.md"};function d(i,a,l,p,h,c){return t(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="redis" tabindex="-1">Redis <a class="header-anchor" href="#redis" aria-label="Permalink to “Redis”">​</a></h1><p>Redis 是一个基于内存的高性能键值数据库。除了 String、Hash、List、Set、ZSet 等基础数据结构，还提供过期、持久化、发布订阅、Stream、Lua、事务等能力。</p><p>实际项目中我主要把它用于：<strong>缓存、分布式锁、计数、限流以及临时状态管理</strong>。本模块按「原理 → 结构 → 场景能力 → 实战」组织，每块强调<strong>怎么用、踩什么坑、怎么优化</strong>，而不是背命令大全。</p><hr><h2 id="学习-面试地图" tabindex="-1">学习 / 面试地图 <a class="header-anchor" href="#学习-面试地图" aria-label="Permalink to “学习 / 面试地图”">​</a></h2><table tabindex="0"><thead><tr><th>分区</th><th>核心问题</th><th>入口</th></tr></thead><tbody><tr><td>1. 基础原理</td><td>是什么、为什么快、线程与 IO</td><td><a href="./01-basics.html">基础原理</a></td></tr><tr><td>2. 数据结构</td><td>选哪种类型、底层与场景</td><td><a href="./data-types.html">数据类型</a> · <a href="./commands-expire.html">命令与过期</a></td></tr><tr><td>3. 缓存</td><td>穿透/击穿/雪崩、热点与一致性</td><td><a href="./cache-issues.html">缓存问题</a></td></tr><tr><td>4. 持久化</td><td>RDB / AOF / 混合与恢复</td><td><a href="./persistence.html">持久化</a></td></tr><tr><td>5. 高可用</td><td>主从、Sentinel、Cluster</td><td><a href="./cluster-ha.html">集群与高可用</a></td></tr><tr><td>6. 分布式</td><td>锁、Redisson、续期与误删</td><td><a href="./distributed-lock.html">分布式锁</a></td></tr><tr><td>7. 并发</td><td>原子、Lua、库存、限流</td><td><a href="./07-concurrency.html">并发与原子</a></td></tr><tr><td>8. 消息</td><td>Pub/Sub、Stream、延迟队列</td><td><a href="./transaction-pubsub.html">消息与事务</a></td></tr><tr><td>9. 性能</td><td>BigKey、HotKey、Pipeline、淘汰</td><td><a href="./09-performance.html">性能优化</a></td></tr><tr><td>10. 实战</td><td>登录、秒杀、点赞、排行榜等</td><td><a href="./10-practice.html">场景实战</a></td></tr></tbody></table><p>快速刷题仍可用：<a href="./overview.html">面试高频总览</a>。<br> 按追问连续口述练：<a href="./interview-chain.html">面试连环追问</a>。</p><hr><h2 id="我怎么定位-redis" tabindex="-1">我怎么定位 Redis <a class="header-anchor" href="#我怎么定位-redis" aria-label="Permalink to “我怎么定位 Redis”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>不是「第二个 MySQL」</span></span>
<span class="line"><span>而是：热数据与协调能力层</span></span>
<span class="line"><span></span></span>
<span class="line"><span>优先：</span></span>
<span class="line"><span>  缓存读路径</span></span>
<span class="line"><span>  分布式互斥（锁）</span></span>
<span class="line"><span>  计数 / 限流 / 会话与临时状态</span></span>
<span class="line"><span></span></span>
<span class="line"><span>谨慎：</span></span>
<span class="line"><span>  当唯一可靠消息队列（复杂投递语义优先 MQ）</span></span>
<span class="line"><span>  当永久主存（要靠持久化 + 备份 + 恢复演练）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><hr><h2 id="核心优化原则-贯穿全模块" tabindex="-1">核心优化原则（贯穿全模块） <a class="header-anchor" href="#核心优化原则-贯穿全模块" aria-label="Permalink to “核心优化原则（贯穿全模块）”">​</a></h2><ol><li><strong>Key 设计规范</strong>：业务前缀 + 明确过期；禁止无 TTL 的大杂烩</li><li><strong>防穿透 / 击穿 / 雪崩</strong>：空值、互斥、过期随机、多级缓存</li><li><strong>锁必须可续期、可校验持有者</strong>：优先 Redisson，忌裸 <code>SETNX</code> 忘记过期</li><li><strong>大 Key / 热 Key 单独治理</strong>：拆分、本地缓存、读写分离或集群槽位感知</li><li><strong>批量用 Pipeline / Lua</strong>：减 RTT；耗时命令与 <code>KEYS *</code> 禁止上生产</li><li><strong>高可用按需求选型</strong>：主从够用就别上 Cluster；Cluster 要懂槽位与跨槽限制</li></ol><p>按左侧菜单分区推进；实战页把能力串成可口述的项目故事。</p>`,14)])])}const m=s(r,[["render",d]]);export{b as __pageData,m as default};
